<script setup>
import {onBeforeUnmount,ref,watch} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';import {useAuth} from '../../composables/useAuth.js';
const props=defineProps({modelValue:String,total:[Number,String],disabled:Boolean}),emit=defineEmits(['update:modelValue']),{user}=useAuth(),balance=ref(null),error=ref('');let revision=0;
async function load(){const ticket=++revision;balance.value=null;error.value='';try{const b=await request('/account/vnd-wallet');if(ticket===revision)balance.value=b;}catch(e){if(ticket===revision)error.value=e.message;}}
watch(()=>user.value?.id,load,{immediate:true});onBeforeUnmount(()=>revision++);
</script>
<template><fieldset class="bm-wallet-checkout" :disabled="disabled"><legend>Phương thức thanh toán</legend><label><input type="radio" name="payment-method" value="COD" :checked="modelValue==='COD'" @change="emit('update:modelValue','COD')"/> Thanh toán COD khi nhận hàng</label><template v-if="balance?.enabled"><label><input type="radio" name="payment-method" value="WALLET_SANDBOX" :checked="modelValue==='WALLET_SANDBOX'" :disabled="!total||balance.available<Number(total)" @change="emit('update:modelValue','WALLET_SANDBOX')"/> Ví BonsaiMarket · thử nghiệm</label><p>Chế độ thử nghiệm — Tiền mô phỏng, không có giá trị thanh toán thực tế.</p><p>Số dư: {{ new Intl.NumberFormat('vi-VN').format(balance.available) }} ₫. {{ balance.available<Number(total)?'Số dư không đủ cho đơn này.':'' }} <RouterLink to="/wallet">Mở ví</RouterLink></p></template><p v-if="error" role="alert">Không kiểm tra được ví. {{ error }} <button type="button" @click="load">Thử lại</button></p></fieldset></template>
<style scoped>.bm-wallet-checkout{border:1px solid var(--bm-border);border-radius:10px;padding:14px;margin-block:16px}.bm-wallet-checkout label{display:flex;align-items:center;gap:10px;min-height:44px}.bm-wallet-checkout p{font-size:13px;line-height:1.6;color:var(--bm-muted)}.bm-wallet-checkout a{color:var(--bm-forest)}.bm-wallet-checkout input{width:18px;height:18px;accent-color:var(--bm-forest)}</style>
